#[%dw 2.0
output application/json
---{
 message:"Your store is not verified yet. You are not allowed to add a product"
}]

munit-tools:assert-that.is:
#[MunitTools::equalTo({
 message:"This store belongs to a different seller. You are not allowed to post products in this store",
 storeId:vars.storeId
})]

munit-tools:assert.munit-tools:that:
#[import * from dw::test::Asserts
---
payload must equalTo({
 message:"product with productId: " ++ vars.productId as String ++ " not found"
})]

